def stable_unique(values):
    seen = set()
    result = []
    for v in values:
        if (isinstance(v, int) or isinstance(v, str)) and not isinstance(v, bool):
            if v not in seen:
                seen.add(v)
                result.append(v)
        else:
            result.append(v)
    return result
```

